import React, { useState } from "react";
import Login from "./components/Login";
import OrderList from "./components/OrderList";

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentView, setCurrentView] = useState("orders");
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  if (!isLoggedIn) {
    return <Login onLogin={() => setIsLoggedIn(true)} />;
  }

  const navButton = (view, label) => (
    <button
      onClick={() => setCurrentView(view)}
      style={{
        background: currentView === view ? "#f97316" : "transparent",
        color: "#f1f5f9",
        border: "none",
        padding: "8px 16px",
        borderRadius: "6px",
        cursor: "pointer",
        fontWeight: "500"
      }}
    >
      {label}
    </button>
  );

  return (
    <div style={{
      minHeight: "100vh",
      background: "#0f172a",
      fontFamily: "Arial, sans-serif"
    }}>
      <nav style={{
        background: "#1e293b",
        borderBottom: "2px solid #f97316",
        padding: "0 24px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        height: "60px"
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: "32px" }}>
          <span style={{
            fontSize: "20px",
            fontWeight: "700",
            color: "#f97316"
          }}>
            🚛 Freight Planner
          </span>
          {navButton("trips", "Keikat")}
          {navButton("orders", "Orderit")}
          {navButton("calculator", "Kustannuslaskin")}
        </div>
        <button
          onClick={() => setIsLoggedIn(false)}
          style={{
            background: "transparent",
            color: "#94a3b8",
            border: "1px solid #475569",
            padding: "8px 16px",
            borderRadius: "6px",
            cursor: "pointer"
          }}
        >
          Kirjaudu ulos
        </button>
      </nav>

      <div style={{ padding: "24px", maxWidth: "1400px", margin: "0 auto" }}>
        {currentView === "orders" && (
          <OrderList
            refreshTrigger={refreshTrigger}
            onSelect={(id) => alert("Order " + id + " — muokkausnäkymä tulossa")}
            onCreate={() => alert("Order-luontilomake tulossa seuraavassa vaiheessa")}
          />
        )}
        {currentView === "trips" && (
          <div style={{ color: "#94a3b8" }}>
            Keikkalista tulossa seuraavissa vaiheissa.
          </div>
        )}
        {currentView === "calculator" && (
          <div style={{ color: "#94a3b8" }}>
            Kustannuslaskin tulossa myöhemmin.
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
